mySet = set('ATGTGGG')
mySet2 = {'ATGCCT'}

print(mySet)
print(mySet2)

# 1. Qual é a diferença?
# set('ATGTGGG') transforma cada caractere da sequência em um elemento do conjunto, eliminando as repetições, enquanto {'ATGCCT'} cria um conjunto contendo uma única string como elemento.#

#2. Importa como você cria o conjunto?
# Sim. A forma de criação importa, principalmente quando queremos criar um conjunto vazio: set() cria um conjunto vazio, enquanto {} cria um dicionário vazio. Além disso, set('ATGTGGG') e {'ATGTGGG'} produzem conjuntos diferentes.

SetA = {3, 14, 15, 9, 26, 5, 35, 9}
SetB = {60, 22, 14, 0, 9}

print("Interseção:", SetA & SetB)
print("Diferença A - B:", SetA - SetB)
print("União:", SetA | SetB)
print("Diferença simétrica:", SetA ^ SetB)

dna = set('')
print("Bases presentes na sequência:", dna)

#Com a criação de um conjunto a partir de uma sequência de DNA, o que obtem-se é um conjunto contendo apenas os nucleotídeos distintos presentes na sequência, com as repetições removidas#


dna = ''''''

unique_chars = set(dna)

nt_comp = {}

for nt in unique_chars:
    nt_comp[nt] = dna.count(nt)

print("Composição de nucleotídeos:")
for nt, count in nt_comp.items():
    print(nt, count)

gc_content = (nt_comp['G'] + nt_comp['C']) / len(dna) * 100

print("Conteúdo de GC:", gc_content, "%")


